public static void tick(boolean start, Level level) {
		if (!level.isClientSide()) {
			IMagnetTracker tracker = getTracker(level);
			if (tracker == null)
				return;

			if (!start) {
				for (BlockPos pos : tracker.getTrackedPositions())
					tracker.actOnForces(pos);
			}
			tracker.clear();
		}
	}

public static void applyForce(Level world, BlockPos pos, int magnitude, boolean pushing, Direction dir, int distance, BlockPos origin) {
		if (!world.isClientSide) {
			IMagnetTracker tracker = getTracker(world);
			if (tracker != null)
				tracker.applyForce(pos, magnitude, pushing, dir, distance, origin);
		}
	}

public static ICollateralMover.MoveResult getPushAction(MagnetBlockEntity magnet, BlockPos pos, BlockState state, Direction moveDir) {
		if(state.getBlock() instanceof MovingMagnetizedBlock)return ICollateralMover.MoveResult.SKIP;


		Level world = magnet.getLevel();
		if(world != null && canBlockBeMagneticallyMoved(state, pos, world, moveDir, magnet)) {
			BlockPos frontPos = pos.relative(moveDir);
			BlockState frontState = world.getBlockState(frontPos);

			if(state.getBlock() instanceof ICollateralMover cm && cm.isCollateralMover(world, magnet.getBlockPos(), moveDir, pos)){
				//now check if block in front is immovable (probably meaning unbreakable)
				if(MagnetsModule.usePistonLogic && !PistonBaseBlock.isPushable(frontState, world, frontPos, moveDir, true, moveDir.getOpposite())){
					return ICollateralMover.MoveResult.PREVENT;
				}
				return cm.getCollateralMovement(world, magnet.getBlockPos(), moveDir, moveDir, pos);
			}

			if(frontState.isAir())
				return ICollateralMover.MoveResult.MOVE;
			else if(frontState.getPistonPushReaction() == PushReaction.DESTROY)
				return ICollateralMover.MoveResult.BREAK;
		}

		return ICollateralMover.MoveResult.SKIP;
	}

public static boolean canBlockBeMagneticallyMoved(BlockState state, BlockPos pos, Level level, Direction moveDir, BlockEntity magnet) {
		Block block = state.getBlock();

		//cant push stuff that pistons cant push
		if(MagnetsModule.usePistonLogic && !PistonBaseBlock.isPushable(state, level, pos, moveDir, true, moveDir.getOpposite())){
			return false;
		}

		if (block == Blocks.PISTON || block == Blocks.STICKY_PISTON) {
			if (state.getValue(PistonBaseBlock.EXTENDED))
				return false;
		}
		if (block == MagnetsModule.magnet || state.isAir()) return false;

		IMagnetMoveAction action = getMoveAction(block);
		if (action != null) return action.canMagnetMove(level, pos, moveDir, state, magnet);
		return (magnetizableBlocks.contains(block));
	}

@Override
	public void applyForce(BlockPos pos, int magnitude, boolean pushing, Direction dir, int distance, BlockPos origin) {
		forcesActing.put(pos, new Force(magnitude, pushing, dir, distance, origin));
	}

@Override
	public Vec3i getNetForce(BlockPos pos) {
		Vec3i net = Vec3i.ZERO;
		for(Force force : forcesActing.get(pos))
			net = force.add(net);
		return net;
	}

@Override
	public void actOnForces(BlockPos pos) {
		Vec3i net = getNetForce(pos);

		if(net.equals(Vec3i.ZERO))
			return;

		Direction target = Direction.getNearest(net.getX(), net.getY(), net.getZ());

		for(Force force : forcesActing.get(pos)) {
			if(force.direction() == target) {
				BlockState origin = world.getBlockState(force.origin());
				//here it assumes that whichever block applied that force is a magnet block... or at least expects these block events
				world.blockEvent(force.origin(), origin.getBlock(), force.pushing() ? 0 : 1, force.distance());
			}
		}
	}

@Override
	public Collection<BlockPos> getTrackedPositions() {
		return forcesActing.keySet();
	}

@Override
	public void clear() {
		forcesActing.clear();
	}

public Vec3i add(Vec3i force) {
		return new Vec3i(force.getX() + direction.getStepX() * magnitude,
				force.getY() + direction.getStepY() * magnitude,
				force.getZ() + direction.getStepZ() * magnitude);
	}

public static void tick(Level level, BlockPos pos, BlockState state, MagnetBlockEntity be) {
        boolean powered = state.getValue(MagnetBlock.POWERED);

        if (powered) {
            Direction dir = state.getValue(MagnetBlock.FACING);
            int power = level.getBestNeighborSignal(pos);
            be.magnetize(state, dir, dir, power);
            be.magnetize(state, dir.getOpposite(), dir, power);
        }
    }

private void magnetize(BlockState state, Direction dir, Direction moveDir, int power) {
        if (level == null)
            return;

        double magnitude = (dir == moveDir ? 1 : -1);

        int blockDist = 1;
        for (; blockDist <= power; blockDist++) {
            BlockPos targetPos = worldPosition.relative(dir, blockDist);
            BlockState targetState = level.getBlockState(targetPos);


            if (!level.isClientSide) {
                var reaction = MagnetSystem.getPushAction(this, targetPos, targetState, moveDir);
                if (reaction == ICollateralMover.MoveResult.MOVE || reaction == ICollateralMover.MoveResult.BREAK) {
                    MagnetSystem.applyForce(level, targetPos, power - blockDist + 1, dir == moveDir, moveDir, blockDist, worldPosition);
                } else if (reaction == ICollateralMover.MoveResult.PREVENT) break;
            }

            if (targetState.getBlock() == MagnetsModule.magnetized_block && level.getBlockEntity(targetPos) instanceof MagnetizedBlockBlockEntity mbe) {
                targetState = mbe.getBlockState();
            }

            if (!canFluxPenetrate(targetPos, targetState)) break;
        }

        //TODO: move this into magnet system. although might not be needed as there it only serves since directions must be discrete
        if (MagnetsModule.affectEntities && blockDist > 1) {
            var entities = level.getEntities((Entity) null, new AABB(worldPosition)
                    .expandTowards(new Vec3(dir.step().mul(blockDist))), this::canPullEntity);
            for (Entity e : entities) {
                pushEntity(dir, magnitude, e);
            }
        }

        //particles
        if (level.isClientSide && !state.getValue(MagnetBlock.WAXED)){

            double particleMotion = 0.06 * magnitude;
            double particleChance = 0.2;
            double xOff = dir.getStepX() * particleMotion;
            double yOff = dir.getStepY() * particleMotion;
            double zOff = dir.getStepZ() * particleMotion;

            double particleOffset = moveDir.getAxisDirection() == Direction.AxisDirection.POSITIVE ? 1 : -1;

            for (int j = 1; j < blockDist; j++) {
                if (level.random.nextFloat() <= particleChance) {
                    BlockPos targetPos = worldPosition.relative(dir, j);
                    double x = targetPos.getX() + getParticlePos(xOff, level.random, particleOffset);
                    double y = targetPos.getY() + getParticlePos(yOff, level.random, particleOffset);
                    double z = targetPos.getZ() + getParticlePos(zOff, level.random, particleOffset);
                    var p = dir == moveDir ? MagnetsModule.repulsorParticle : MagnetsModule.attractorParticle;

                    level.addParticle(p, x, y, z, xOff, yOff, zOff);
                }
            }
        }
    }

@Override
	public boolean triggerEvent(BlockState state, Level world, BlockPos pos, int action, int data) {
		boolean push = action == 0;
		Direction moveDir = state.getValue(FACING);
		Direction dir = push ? moveDir : moveDir.getOpposite();

		BlockPos targetPos = pos.relative(dir, data);
		BlockState targetState = world.getBlockState(targetPos);

		if(!(world.getBlockEntity(pos) instanceof MagnetBlockEntity be))
			return false;

		BlockPos endPos = targetPos.relative(moveDir);
		var reaction = MagnetSystem.getPushAction(be, targetPos, targetState, moveDir);
		if(reaction != ICollateralMover.MoveResult.MOVE && reaction != ICollateralMover.MoveResult.BREAK)
			return false;

		BlockEntity tilePresent = world.getBlockEntity(targetPos);
		CompoundTag tileData = new CompoundTag();
		if(tilePresent != null && !(tilePresent instanceof MagnetizedBlockBlockEntity)) {
			tileData = tilePresent.saveWithFullMetadata(world.registryAccess());
			tilePresent.setRemoved();
		}

		BlockState setState = MagnetsModule.magnetized_block.defaultBlockState().setValue(MovingMagnetizedBlock.FACING, moveDir);
		MagnetizedBlockBlockEntity movingTile = new MagnetizedBlockBlockEntity(endPos, setState, targetState, tileData, moveDir);

		if(!world.isClientSide && reaction == ICollateralMover.MoveResult.BREAK) {
			world.destroyBlock(endPos, true);
		}

		world.setBlock(endPos, setState, 68);
		world.setBlockEntity(movingTile);

		world.setBlock(targetPos, Blocks.AIR.defaultBlockState(), 67);

		return true;
	}

@Override
	public void onRemove(BlockState state, @NotNull Level worldIn, @NotNull BlockPos pos, @NotNull BlockState newState, boolean isMoving) {
		if(state.getBlock() != newState.getBlock()) {
			MagnetizedBlockBlockEntity tile = getMagnetTileEntity(worldIn, pos);
			if(tile != null)
				tile.clearMagnetTileEntity();
		}
	}

