@Nullable
	private MagnetizedBlockBlockEntity getMagnetTileEntity(BlockGetter world, BlockPos pos) {
		BlockEntity tile = world.getBlockEntity(pos);
		return tile instanceof MagnetizedBlockBlockEntity ? (MagnetizedBlockBlockEntity) tile : null;
	}

public void clearMagnetTileEntity() {
		if(this.lastProgress < 1.0F && this.level != null) {
			this.progress = 1.0F;
			this.lastProgress = this.progress;

			this.level.removeBlockEntity(this.worldPosition);
			this.setRemoved();
			if(this.level.getBlockState(this.worldPosition).getBlock() == MagnetsModule.magnetized_block) {
				BlockState blockstate = Block.updateFromNeighbourShapes(this.magnetState, this.level, this.worldPosition);
				setAndUpdateBlock(blockstate, 3);
			}
		}

	}

private void setAndUpdateBlock(BlockState blockstate, int flag) {
		if(this.level == null)
			return;
		this.level.setBlock(this.worldPosition, blockstate, flag);
		this.level.neighborChanged(this.worldPosition, blockstate.getBlock(), this.worldPosition);
		if((blockstate.getBlock() instanceof ButtonBlock || blockstate.getBlock() instanceof BasePressurePlateBlock) &&
				this.level instanceof ServerLevel serverLevel) {
			blockstate.tick(serverLevel, this.worldPosition, serverLevel.random);
			blockstate = this.level.getBlockState(this.worldPosition);
		}

		finalizeContents(blockstate);
    }

public void finalizeContents(BlockState blockState) {
		if(level == null || level.isClientSide)
			return;

		SoundType soundType = blockState.getSoundType();
		level.playSound(null, worldPosition, soundType.getPlaceSound(), SoundSource.BLOCKS, (soundType.getVolume() + 1) * 0.05F, soundType.getPitch() * 0.8F);

		BlockEntity newTile = getSubTile(worldPosition);
		if(newTile != null) {
            level.setBlockEntity(newTile);
            level.updateNeighbourForOutputSignal(worldPosition, blockState.getBlock());
        }

		IMagnetMoveAction action = getMoveAction();
		if(action != null)
			action.onMagnetMoved(level, worldPosition, magnetFacing, blockState, newTile);
	}

public BlockEntity getSubTile(BlockPos pos) {
		if(subTile != null && !subTile.isEmpty()) {
			CompoundTag tileData = subTile.copy();
			tileData.putInt("x", this.worldPosition.getX());
			tileData.putInt("y", this.worldPosition.getY());
			tileData.putInt("z", this.worldPosition.getZ());
			return BlockEntity.loadStatic(pos, magnetState, subTile, level.registryAccess());
		}
		return null;
	}

private void moveCollidedEntities(float progress) {
		if(this.level == null)
			return;

		boolean sticky = Quark.ZETA.blockExtensions.get(magnetState).isStickyBlockZeta(magnetState);

		Direction direction = this.magnetFacing;
		double movement = (progress - this.progress);
		VoxelShape collision = magnetState.getCollisionShape(this.level, this.getBlockPos());
		if(!collision.isEmpty()) {
			List<AABB> boundingBoxes = collision.toAabbs();
			AABB containingBox = this.moveByPositionAndProgress(this.getEnclosingBox(boundingBoxes));
			List<Entity> entities = this.level.getEntities(null, this.getMovementArea(containingBox, direction, movement).minmax(containingBox));
			if(!entities.isEmpty()) {

				for(Entity entity : entities) {
					if(entity.getPistonPushReaction() != PushReaction.IGNORE) {
						if(sticky) {
							Vec3 motion = entity.getDeltaMovement();
							double dX = motion.x;
							double dY = motion.y;
							double dZ = motion.z;
							switch(direction.getAxis()) {
							case X -> dX = direction.getStepX();
							case Y -> dY = direction.getStepY();
							case Z -> dZ = direction.getStepZ();
							}

							entity.setDeltaMovement(dX, dY, dZ);
						}

						double motion = 0.0D;

						for(AABB aList : boundingBoxes) {
							AABB movementArea = this.getMovementArea(this.moveByPositionAndProgress(aList), direction, movement);
							AABB entityBox = entity.getBoundingBox();
							if(movementArea.intersects(entityBox)) {
								motion = Math.max(motion, this.getMovement(movementArea, direction, entityBox));
								if(motion >= movement) {
									break;
								}
							}
						}

						if(motion > 0) {
							motion = Math.min(motion, movement) + 0.01D;
							MOVING_ENTITY.set(direction);
							entity.move(MoverType.PISTON, new Vec3(motion * direction.getStepX(), motion * direction.getStepY(), motion * direction.getStepZ()));
							MOVING_ENTITY.set(null);
						}
					}
				}

			}
		}
	}

public VoxelShape getCollisionShape(BlockGetter world, BlockPos pos) {
		Direction direction = MOVING_ENTITY.get();
		if(this.progress < 1.0D && direction == this.magnetFacing) {
			return Shapes.empty();
		} else {

			float progress = this.getExtendedProgress(this.progress);
			double dX = this.magnetFacing.getStepX() * progress;
			double dY = this.magnetFacing.getStepY() * progress;
			double dZ = this.magnetFacing.getStepZ() * progress;
			return magnetState.getCollisionShape(world, pos).move(dX, dY, dZ);
		}
	}

@Override
	protected void loadAdditional(CompoundTag tag, HolderLookup.Provider provider) {
		super.loadAdditional(tag, provider);
		this.magnetState = NbtUtils.readBlockState(level.holderLookup(Registries.BLOCK), tag.getCompound("blockState"));
		this.magnetFacing = Direction.from3DDataValue(tag.getInt("facing"));
		this.progress = tag.getFloat("progress");
		this.lastProgress = this.progress;
		this.subTile = tag.getCompound("subTile");
	}

private CompoundTag writeNBTData(CompoundTag compound, boolean includeSubTile) {
		if (compound == null) {
			compound = new CompoundTag();
		}
		compound.put("blockState", NbtUtils.writeBlockState(this.magnetState));
		if(includeSubTile)
			compound.put("subTile", subTile);
		compound.putInt("facing", this.magnetFacing.get3DDataValue());
		compound.putFloat("progress", this.lastProgress);
		return compound;
	}

private boolean doCasting(World world, EntityLivingBase caster, SpellModifiers modifiers){

		if(world.canBlockSeeSky(new BlockPos(caster))){

			double maxRadius = getProperty(EFFECT_RADIUS).doubleValue();

			for(int i = 0; i < getProperty(LIGHTNING_BOLTS).intValue(); i++){

				double radius = maxRadius * CENTRE_RADIUS_FRACTION + world.rand.nextDouble() * maxRadius
						* (1 - CENTRE_RADIUS_FRACTION) * modifiers.get(WizardryItems.blast_upgrade);
				float angle = world.rand.nextFloat() * (float)Math.PI * 2;

				double x = caster.posX + radius * MathHelper.cos(angle);
				double z = caster.posZ + radius * MathHelper.sin(angle);
				Integer y = BlockUtils.getNearestFloor(world, new BlockPos(x, caster.posY, z), (int)maxRadius);

				if(y != null){

					if(!world.isRemote){
						EntityLightningBolt lightning = new EntityLightningBolt(world, x, y, z, false);
						lightning.getEntityData().setUniqueId(LightningBolt.SUMMONER_NBT_KEY, caster.getUniqueID());
						lightning.getEntityData().setFloat(LightningBolt.DAMAGE_MODIFIER_NBT_KEY, modifiers.get(SpellModifiers.POTENCY));
						world.addWeatherEffect(lightning);
					}

					// Secondary chaining effect
					List<EntityLivingBase> secondaryTargets = EntityUtils.getLivingWithinRadius(
							getProperty(SECONDARY_RANGE).doubleValue(), x, y + 1, z, world);

					for(int j = 0; j < Math.min(secondaryTargets.size(), getProperty(SECONDARY_MAX_TARGETS).intValue()); j++){

						EntityLivingBase secondaryTarget = secondaryTargets.get(j);

						if(AllyDesignationSystem.isValidTarget(caster, secondaryTarget)){

							if(world.isRemote){

								ParticleBuilder.create(Type.LIGHTNING).pos(x, y, z).target(secondaryTarget).spawn(world);

								ParticleBuilder.spawnShockParticles(world, secondaryTarget.posX,
										secondaryTarget.posY + secondaryTarget.height / 2,
										secondaryTarget.posZ);
							}

							playSound(world, secondaryTarget, 0, -1, modifiers);

							secondaryTarget.attackEntityFrom(MagicDamage.causeDirectMagicDamage(caster, DamageType.SHOCK),
									getProperty(SECONDARY_DAMAGE).floatValue() * modifiers.get(SpellModifiers.POTENCY));

							// Tertiary chaining effect

							List<EntityLivingBase> tertiaryTargets = EntityUtils.getLivingWithinRadius(
									getProperty(TERTIARY_RANGE).doubleValue(), secondaryTarget.posX,
									secondaryTarget.posY + secondaryTarget.height / 2, secondaryTarget.posZ, world);

							for(int k = 0; k < Math.min(tertiaryTargets.size(), getProperty(TERTIARY_MAX_TARGETS).intValue()); k++){

								EntityLivingBase tertiaryTarget = tertiaryTargets.get(k);

								if(!secondaryTargets.contains(tertiaryTarget)
										&& AllyDesignationSystem.isValidTarget(caster, tertiaryTarget)){

									if(world.isRemote){
										ParticleBuilder.create(Type.LIGHTNING).entity(secondaryTarget)
												.pos(0, secondaryTarget.height / 2, 0).target(tertiaryTarget).spawn(world);
										ParticleBuilder.spawnShockParticles(world, tertiaryTarget.posX,
												tertiaryTarget.posY + tertiaryTarget.height / 2,
												tertiaryTarget.posZ);
									}

									playSound(world, tertiaryTarget, 0, -1, modifiers);

									tertiaryTarget.attackEntityFrom(
											MagicDamage.causeDirectMagicDamage(caster, DamageType.SHOCK),
											getProperty(TERTIARY_DAMAGE).floatValue() * modifiers.get(SpellModifiers.POTENCY));
								}
							}
						}
					}
				}
			}

			return true;
		}

		return false;
	}

@Override
	public boolean cast(World world, EntityPlayer caster, EnumHand hand, int ticksInUse, SpellModifiers modifiers){
		return doCasting(world, caster, modifiers);
	}

@Override
	public boolean cast(World world, EntityLiving caster, EnumHand hand, int ticksInUse, EntityLivingBase target, SpellModifiers modifiers){
		return doCasting(world, caster, modifiers);
	}

@SubscribeEvent(priority = EventPriority.LOW)
	public static void onEntityStruckByLightningEvent(EntityStruckByLightningEvent event){

		float damageModifier = event.getLightning().getEntityData().getFloat(DAMAGE_MODIFIER_NBT_KEY);

		Entity summoner = null;

		if(event.getLightning().getEntityData().hasUniqueId(SUMMONER_NBT_KEY)){

			summoner = EntityUtils.getEntityByUUID(event.getLightning().world,
					event.getLightning().getEntityData().getUniqueId(SUMMONER_NBT_KEY));

			if(!(summoner instanceof EntityLivingBase)) summoner = null;
		}

		if(damageModifier > 0 || summoner != null){

			DamageSource source = summoner == null ? DamageSource.LIGHTNING_BOLT
					: MagicDamage.causeIndirectMagicDamage(event.getLightning(), summoner, DamageType.SHOCK);
			float damage = Spells.lightning_bolt.getProperty(DAMAGE).floatValue() * damageModifier;

			// Don't need DamageSafetyChecker here because this isn't an attack event
			EntityUtils.attackEntityWithoutKnockback(event.getEntity(), source, damage);
			event.getEntity().getEntityData().setBoolean(IMMUNE_TO_LIGHTNING_NBT_KEY, true);
		}
	}

@SubscribeEvent(priority = EventPriority.HIGHEST)
	public static void onLivingAttackEvent(LivingAttackEvent event){
		if(event.getEntity().getEntityData().hasKey(IMMUNE_TO_LIGHTNING_NBT_KEY)
				&& event.getSource() == DamageSource.LIGHTNING_BOLT){
			event.setCanceled(true);
			event.getEntity().getEntityData().removeTag(IMMUNE_TO_LIGHTNING_NBT_KEY);
		}
	}

@Nullable
	public static Entity getEntityByUUID(World world, @Nullable UUID id){

		if(id == null) return null; // It would return null eventually but there's no point even looking

		for(Entity entity : world.loadedEntityList){
			// This is a perfect example of where you need to use .equals() and not ==. For most applications,
			// this was unnoticeable until world reload because the UUID instance or entity instance is stored.
			// Fixed now though.
			if(entity != null && entity.getUniqueID() != null && entity.getUniqueID().equals(id)){
				return entity;
			}
		}
		return null;
	}

public static boolean attackEntityWithoutKnockback(Entity entity, DamageSource source, float amount){
		double vx = entity.motionX;
		double vy = entity.motionY;
		double vz = entity.motionZ;
		boolean succeeded = entity.attackEntityFrom(source, amount);
		entity.motionX = vx;
		entity.motionY = vy;
		entity.motionZ = vz;
		return succeeded;
	}

@Override
    protected void tick() {
        Level world = getWorld();
        int radius = 3;
        if (world.isClientSide) {
            BlockPos pos = getPos();
            ParticleUtil.spawnRitualAreaEffect(getPos(), getWorld(), rand, getCenterColor(), radius);
        }
        if (!getWorld().isClientSide && world.getGameTime() % 60 == 0) {
            boolean didWorkOnce = false;
            Level level = getWorld();
            BlockPos pos = getPos();
            //Get nearby source jars
            for (BlockPos blockPos : BlockPos.betweenClosed(pos.offset(-radius, -radius, -radius), pos.offset(radius, radius, radius))) {
                if (level.getBlockState(blockPos).getBlock() instanceof MobJar) {
                    MobJarTile tile = (MobJarTile) level.getBlockEntity(blockPos);
                    if (tile == null || tile.getEntity() != null) {
                        continue;
                    }
                    for (Entity e : level.getEntities((Entity) null, new AABB(tile.getBlockPos()).inflate(5), this::canJar)) {
                        for (var passenger : e.getPassengers()) {
                            passenger.stopRiding();
                        }
                        if (e instanceof Mob mob && ((Mob) e).isLeashed() && e.shouldBeSaved()) {
                            if (mob.isLeashed()) {
                                mob.dropLeash(true, true);
                            }
                        }
                        if (e instanceof Raider raider && raider.hasActiveRaid()) {
                            raider.getCurrentRaid().removeFromRaid(raider, false);
                        }
                        if (e instanceof Villager villager) {
                            villager.releasePoi(MemoryModuleType.HOME);
                            villager.releasePoi(MemoryModuleType.JOB_SITE);
                            villager.releasePoi(MemoryModuleType.POTENTIAL_JOB_SITE);
                            villager.releasePoi(MemoryModuleType.MEETING_POINT);
                        }
                        if (tile.setEntityData(e)) {
                            e.remove(Entity.RemovalReason.UNLOADED_TO_CHUNK);
                            EntityFlyingItem followProjectile = new EntityFlyingItem(level, e.position, Vec3.atCenterOf(tile.getBlockPos()), 100, 50, 100);
                            level.addFreshEntity(followProjectile);
                            ParticleUtil.spawnPoof((ServerLevel) level, e.getOnPos().above());
                            didWorkOnce = true;
                            if (e instanceof Starbuncle starbuncle) {
                                ANCriteriaTriggers.rewardNearbyPlayers(ANCriteriaTriggers.SHRUNK_STARBY.get(), (ServerLevel) level, starbuncle.blockPosition(), 10);
                            }
                            if (e instanceof LightningBolt bolt) {
                                ANCriteriaTriggers.rewardNearbyPlayers(ANCriteriaTriggers.CAUGHT_LIGHTNING.get(), (ServerLevel) level, bolt.blockPosition(), 10);
                            }
                            if (e instanceof ItemEntity item && item.getItem().getItem() == Items.CLOCK) {
                                ANCriteriaTriggers.rewardNearbyPlayers(ANCriteriaTriggers.TIME_IN_BOTTLE.get(), (ServerLevel) level, item.blockPosition(), 10);
                            }
                            break;
                        }
                    }
                }
            }
            if (didWorkOnce) {
                this.setNeedsSource(true);
            }
        }
    }

public boolean canJar(Entity e) {
        if (e.getType().is(EntityTags.JAR_WHITELIST))
            return true;
        if (e.getType().is(EntityTags.JAR_BLACKLIST)) {
            return false;
        }

        if (e instanceof PartEntity) {
            return false;
        }

        if (e instanceof ItemEntity item && item.getItem().is(ItemTagProvider.JAR_ITEM_CAPTURE_BLACKLIST)) {
            return false;
        }

        return e instanceof LivingEntity livingEntity && !(e instanceof Player) && !livingEntity.isDeadOrDying();
    }

