public void removeEntity() {
        if (this.getEntity() instanceof Entity e) {
            e.remove(Entity.RemovalReason.UNLOADED_WITH_PLAYER);
        }
        this.entityTag = null;
        this.cachedEntity = null;
        this.extraDataTag = null;
        this.invalidateCapabilities();
        updateBlock();
    }

@Override
    public void saveAdditional(@NotNull CompoundTag tag, HolderLookup.@NotNull Provider pRegistries) {
        super.saveAdditional(tag, pRegistries);

        // Check both conditions because the entity may have never been loaded on the server side.
        if (entityTag != null || cachedEntity != null) {
            // We cannot run getEntity when the level is null
            if (level == null) {
                if (entityTag != null) {
                    tag.put("entityTag", entityTag);
                }
            } else {
                cachedEntity = getEntity();
                try {
                    if (cachedEntity != null) {
                        tag.put("entityTag", saveEntityToTag(cachedEntity));
                        if (tag.getCompound("entityTag").contains("id")) {
                            tag.putString("entityId", tag.getCompound("entityTag").getString("id"));
                        }
                    }
                } catch (Exception e) {
                    tag.put("entityTag", entityTag);
                    Log.getLogger().warn("Failed to save entity in MobJarTile", e);
                }
            }
        }
        if (extraDataTag != null) {
            tag.put("extraMobData", extraDataTag);
        }
    }

@Override
    protected void loadAdditional(@NotNull CompoundTag pTag, HolderLookup.@NotNull Provider pRegistries) {
        super.loadAdditional(pTag, pRegistries);
        if (pTag.contains("entityTag")) {
            this.entityTag = pTag.getCompound("entityTag");
            this.cachedEntity = null;
        }
        this.extraDataTag = pTag.getCompound("extraMobData");
    }

public static Entity loadEntityFromTag(Level level, CompoundTag tag) {
        Entity entity = EntityType.loadEntityRecursive(tag, level, Function.identity());
        if (entity == null) {
            String id = tag.getString("id");
            Optional<EntityType<?>> type = EntityType.byString(id);
            if (type.isPresent()) {
                entity = type.get().create(level);
            }
        }
        return entity;
    }

public CompoundTag saveEntityToTag(Entity entity) {
        CompoundTag tag = new CompoundTag();
        if (entity != null) {
            entity.save(tag);
            if (tag.isEmpty()) {
                tag.putString("id", EntityType.getKey(entity.getType()).toString());
            }
        }
        return tag;
    }

@Override
    public void tick() {
        super.tick();
        this.age++;


        if (age > 400)
            this.remove(RemovalReason.DISCARDED);

        Vec3 start = entityData.get(from);
        Vec3 end = entityData.get(to);
        if (BlockUtil.distanceFrom(level, end, this.position()) <= 1 || this.age > 1000 || BlockUtil.distanceFrom(level, end, this.position()) > 16) {
            this.remove(RemovalReason.DISCARDED);
            if (level.isClientSide && entityData.get(SPAWN_TOUCH)) {
                ParticleUtil.spawnTouch((ClientLevel) level, BlockPos.containing(end.x, end.y, end.z), new ParticleColor(this.entityData.get(RED), this.entityData.get(GREEN), this.entityData.get(BLUE)));
            }
            return;
        }

        double posX = getX();
        double posY = getY();
        double posZ = getZ();


        double time = 1 - normalize(age, 0.0, 80);

        EasingType type = EasingType.NONE;

        double startY = start.y();
        double endY = end.y() + getDistanceAdjustment(start, end);
        double lerpX = lerp(time, start.x(), end.x(), type);
        double lerpY = lerp(time, lerp(time, startY, endY, type), lerp(time, endY, startY, type), type);
        double lerpZ = lerp(time, start.z(), end.z(), type);

        Vec3 adjustedPos = new Vec3(posX, end.y(), posZ);
        if (BlockUtil.distanceFrom(level, end, adjustedPos) <= 0.5) {
            posY = getY() - 0.05;
            this.setPos(lerpX, posY, lerpZ);
        } else {
            this.setPos(lerpX, lerpY, lerpZ);
        }

        if (level.isClientSide && this.age > 1 && !this.getEntityData().get(IS_BUBBLE)) {
            double deltaX = getX() - xOld;
            double deltaY = getY() - yOld;
            double deltaZ = getZ() - zOld;
            double dist = Math.ceil(Math.sqrt(deltaX * deltaX + deltaY * deltaY + deltaZ * deltaZ) * 20);
            int counter = 0;

            for (double i = 0; i < dist; i++) {
                double coeff = i / dist;
                counter += level.random.nextInt(3);
                if (counter % (Minecraft.getInstance().options.particles().get().getId() == 0 ? 1 : 2 * Minecraft.getInstance().options.particles().get().getId()) == 0) {
                    level.addAlwaysVisibleParticle(GlowParticleData.createData(
                                    new ParticleColor(this.entityData.get(RED), this.entityData.get(GREEN), this.entityData.get(BLUE))),
                            true,
                            (float) (xo + deltaX * coeff), (float) (yo + deltaY * coeff), (float) (zo + deltaZ * coeff), 0.0125f * (random.nextFloat() - 0.5f), 0.0125f * (random.nextFloat() - 0.5f), 0.0125f * (random.nextFloat() - 0.5f));
                }
            }

        }
    }

